class Solution {
    public String restoreString(String text,int[] indices){
        char[] answer=new char[text.length()];
        for(int i=0;i<text.length();i++)answer[indices[i]]=text.charAt(i);
        return new String(answer);
    }
}

code.kotlin:
class Solution {
    fun restoreString(text:String,indices:IntArray):String{
        val answer=CharArray(text.length);
        for(i in text.indices)answer[indices[i]]=text[i];
        return answer.concatToString()
    }
}

code.cpp:
class Solution {
    public: string restoreString(string text,vector<int>& indices){
        string answer(text.size(),' ');
        for(int i=0;i<(int)text.size();++i)answer[indices[i]]=text[i];
        return answer;
    }
};
